using System;using System.Linq;using dnlib.DotNet;using dnlib.DotNet.Emit;using dnlib.DotNet.Writer;
using var m=ModuleDefMD.Load(args[0]);using var h=ModuleDefMD.Load(args[1]);var importer=new Importer(m);var helper=h.Types.Single(t=>t.Name=="SoulFormationDiagnostics");var attach=importer.Import(helper.Methods.Single(x=>x.Name=="Attach"));var dump=importer.Import(helper.Methods.Single(x=>x.Name=="Dump"));var p=m.GetTypes().Single(t=>t.FullName=="UI.UIFormationPopupPage");foreach(var name in new[]{"InitPage","SetModelPos"}){var method=p.Methods.Single(x=>x.Name==name);foreach(var ret in method.Body.Instructions.Where(i=>i.OpCode==OpCodes.Ret).ToArray()){int i=method.Body.Instructions.IndexOf(ret);method.Body.Instructions.Insert(i++,Instruction.Create(OpCodes.Ldarg_0));if(name=="SetModelPos")method.Body.Instructions.Insert(i++,Instruction.Create(OpCodes.Ldstr,"positioned"));method.Body.Instructions.Insert(i,Instruction.Create(OpCodes.Call,name=="InitPage"?attach:dump));}method.Body.KeepOldMaxStack=true;}var options=new ModuleWriterOptions(m);options.MetadataOptions.Flags|=MetadataFlags.PreserveAll|MetadataFlags.KeepOldMaxStack;m.Write(args[2],options);
